package environment

import (
	"sort"
	"strings"
	"sync"
)

// defaultProviderCredentialEnvBlocklistNames names Hermes/Gormes-managed
// provider credentials that skills must not be allowed to smuggle into
// sandboxed child processes. Keep provider credential families complete; for
// example, AWS credentials are an access-key/secret/session-token triplet.
// Non-provider third party keys such as TENOR_API_KEY remain registerable.
var defaultProviderCredentialEnvBlocklistNames = []string{
	"ANTHROPIC_API_KEY",
	"ANTHROPIC_AUTH_TOKEN",
	"ANTHROPIC_TOKEN",
	"AWS_ACCESS_KEY_ID",
	"AWS_SECRET_ACCESS_KEY",
	"AWS_SESSION_TOKEN",
	"AZURE_OPENAI_API_KEY",
	"COHERE_API_KEY",
	"GEMINI_API_KEY",
	"GOOGLE_API_KEY",
	"GROQ_API_KEY",
	"MISTRAL_API_KEY",
	"NOUS_API_KEY",
	"OPENAI_API_KEY",
	"OPENROUTER_API_KEY",
	"XAI_API_KEY",
}

// ProviderCredentialEnvBlocklist is the mutable provider credential blocklist
// used when new session registries are constructed. Existing registries keep a
// construction-time snapshot so later mutations cannot cross session bounds.
var ProviderCredentialEnvBlocklist = envNameSetFromList(defaultProviderCredentialEnvBlocklistNames)

// EnvPassthroughRegistry is a session-scoped allowlist for environment
// variables that may pass through to sandboxed tools. It mirrors Hermes'
// ContextVar-backed registry with an explicit Go object so callers can keep
// separate sessions isolated and tests can prove no cross-session bleed.
type EnvPassthroughRegistry struct {
	mu         sync.RWMutex
	registered map[string]struct{}
	configured map[string]struct{}
	blocklist  map[string]struct{}
}

// NewEnvPassthroughRegistry creates a registry with config-sourced allowlist
// entries. Provider credentials in the configured list are ignored, matching
// Hermes' safety rule that operator config also cannot override sandbox
// credential scrubbing.
func NewEnvPassthroughRegistry(configured []string) *EnvPassthroughRegistry {
	r := &EnvPassthroughRegistry{
		registered: map[string]struct{}{},
		configured: map[string]struct{}{},
		blocklist:  cloneEnvNameSet(ProviderCredentialEnvBlocklist),
	}
	for _, raw := range configured {
		candidate := classifyEnvPassthroughCandidate(raw, r.blocklist)
		if !candidate.Valid || candidate.ProviderCredential {
			continue
		}
		r.configured[candidate.Name] = struct{}{}
	}
	return r
}

// Register adds skill-declared environment variables to the session allowlist
// and returns the sanitized names that were rejected as provider credentials.
func (r *EnvPassthroughRegistry) Register(names []string) []string {
	if r == nil {
		return nil
	}
	r.mu.Lock()
	defer r.mu.Unlock()

	blocked := make([]string, 0)
	for _, raw := range names {
		candidate := classifyEnvPassthroughCandidate(raw, r.blocklist)
		if !candidate.Valid {
			continue
		}
		if candidate.ProviderCredential {
			blocked = append(blocked, candidate.Name)
			continue
		}
		r.registered[candidate.Name] = struct{}{}
	}
	return blocked
}

// IsAllowed reports whether name was registered for this session or listed in
// the config allowlist.
func (r *EnvPassthroughRegistry) IsAllowed(name string) bool {
	if r == nil {
		return false
	}
	r.mu.RLock()
	defer r.mu.RUnlock()

	candidate := classifyEnvPassthroughCandidate(name, r.blocklist)
	if !candidate.Valid || candidate.ProviderCredential {
		return false
	}
	if _, ok := r.registered[candidate.Name]; ok {
		return true
	}
	_, ok := r.configured[candidate.Name]
	return ok
}

// All returns the sorted union of session-registered and configured allowlist
// names. Sorting keeps tool/runtime evidence deterministic.
func (r *EnvPassthroughRegistry) All() []string {
	if r == nil {
		return nil
	}
	r.mu.RLock()
	defer r.mu.RUnlock()

	return sortedEnvNameUnion(r.registered, r.configured)
}

// ClearRegistered resets only the skill/session-scoped allowlist. Configured
// allowlist entries remain, matching Hermes' clear_env_passthrough semantics.
func (r *EnvPassthroughRegistry) ClearRegistered() {
	if r == nil {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()

	clear(r.registered)
}

func (r *EnvPassthroughRegistry) isProviderCredential(name string) bool {
	if r == nil {
		return false
	}
	r.mu.RLock()
	defer r.mu.RUnlock()

	return isProviderCredentialName(name, r.blocklist)
}

type envPassthroughCandidate struct {
	Name               string
	Valid              bool
	ProviderCredential bool
}

func classifyEnvPassthroughCandidate(raw string, blocklist map[string]struct{}) envPassthroughCandidate {
	name := normalizeEnvPassthroughName(raw)
	if !isValidEnvPassthroughName(name) {
		return envPassthroughCandidate{}
	}
	return envPassthroughCandidate{
		Name:               name,
		Valid:              true,
		ProviderCredential: isProviderCredentialName(name, blocklist),
	}
}

func normalizeEnvPassthroughName(name string) string {
	return strings.TrimSpace(name)
}

func isValidEnvPassthroughName(name string) bool {
	if name == "" {
		return false
	}
	for i := 0; i < len(name); i++ {
		b := name[i]
		if i == 0 {
			if !isEnvPassthroughNameStart(b) {
				return false
			}
			continue
		}
		if !isEnvPassthroughNamePart(b) {
			return false
		}
	}
	return true
}

func isEnvPassthroughNameStart(b byte) bool {
	return b == '_' || ('A' <= b && b <= 'Z') || ('a' <= b && b <= 'z')
}

func isEnvPassthroughNamePart(b byte) bool {
	return isEnvPassthroughNameStart(b) || ('0' <= b && b <= '9')
}

func isProviderCredentialName(name string, blocklist map[string]struct{}) bool {
	if blocklist == nil {
		return false
	}
	_, ok := blocklist[canonicalProviderCredentialName(name)]
	return ok
}

func cloneEnvNameSet(in map[string]struct{}) map[string]struct{} {
	out := make(map[string]struct{}, len(in))
	for name := range in {
		canonical := canonicalProviderCredentialName(name)
		if canonical == "" {
			continue
		}
		out[canonical] = struct{}{}
	}
	return out
}

func envNameSetFromList(names []string) map[string]struct{} {
	out := make(map[string]struct{}, len(names))
	for _, name := range names {
		canonical := canonicalProviderCredentialName(name)
		if canonical == "" {
			continue
		}
		out[canonical] = struct{}{}
	}
	return out
}

func sortedEnvNameUnion(sets ...map[string]struct{}) []string {
	size := 0
	for _, set := range sets {
		size += len(set)
	}
	union := make(map[string]struct{}, size)
	for _, set := range sets {
		for name := range set {
			union[name] = struct{}{}
		}
	}
	out := make([]string, 0, len(union))
	for name := range union {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

func canonicalProviderCredentialName(name string) string {
	return strings.ToUpper(strings.TrimSpace(name))
}

package environment

import "strings"

// SnapshotMode controls whether the terminal-environment shell wrapper
// sources a persisted bash environment snapshot before running a user
// command. The wrapper exists so future Goncho/Hermes terminal backends can
// preserve environment variables across tool invocations without leaking the
// snapshot's `declare -x` lines into the model-visible output (Hermes commit
// 2e6699b3, tools/environments/base.py::BaseEnvironment._wrap_command).
type SnapshotMode int

const (
	// SnapshotDisabled returns the user command verbatim. No snapshot
	// loading is emitted.
	SnapshotDisabled SnapshotMode = iota
	// SnapshotEnabled prefixes the user command with a silenced
	// `source <path>` line that suppresses both stdout and stderr.
	SnapshotEnabled
)

// Evidence codes for EnvironmentSnapshotEvidence.Code.
const (
	EvidenceSnapshotLoaded      = "snapshot_loaded"
	EvidenceSnapshotDisabled    = "snapshot_disabled"
	EvidenceSnapshotPathMissing = "snapshot_path_missing"
)

// EnvironmentSnapshotConfig configures BuildShellWrapper.
type EnvironmentSnapshotConfig struct {
	// Mode selects whether to emit the snapshot-source prefix.
	Mode SnapshotMode
	// SnapshotPath is the absolute path to the persisted bash environment
	// dump (typically the output of `export -p` plus filtered functions
	// and aliases). Empty paths fall back to disabled behavior.
	SnapshotPath string
}

// EnvironmentSnapshotEvidence is telemetry about wrapper construction.
type EnvironmentSnapshotEvidence struct {
	// Code is one of EvidenceSnapshotLoaded, EvidenceSnapshotDisabled, or
	// EvidenceSnapshotPathMissing.
	Code string
	// Path echoes the requested snapshot path so callers can record it
	// even when the wrapper falls through.
	Path string
}

// BuildShellWrapper returns a shell-script string that, when enabled, loads a
// persisted environment snapshot with stdout AND stderr redirected to
// /dev/null before running the user command verbatim. macOS bash 3.2 emits
// `declare -x` lines to stdout when sourcing such a file, which would leak
// the developer's environment variables into every tool response unless both
// streams are suppressed (Hermes 2e6699b3 fix).
//
// When Mode is SnapshotDisabled or SnapshotPath is empty, the user command
// is returned untouched and the evidence reports the fall-through reason.
//
// The user command is never wrapped in its own /dev/null redirect — only the
// snapshot-load line is silenced so the actual command output remains
// visible to the caller.
func BuildShellWrapper(cfg EnvironmentSnapshotConfig, userCommand string) (string, EnvironmentSnapshotEvidence) {
	if cfg.Mode != SnapshotEnabled {
		return userCommand, EnvironmentSnapshotEvidence{
			Code: EvidenceSnapshotDisabled,
			Path: cfg.SnapshotPath,
		}
	}
	if cfg.SnapshotPath == "" {
		return userCommand, EnvironmentSnapshotEvidence{
			Code: EvidenceSnapshotPathMissing,
			Path: "",
		}
	}

	// Source the snapshot with both stdout and stderr redirected, then run
	// the user command verbatim on the next line. `|| true` keeps the
	// wrapper resilient to a missing/corrupt snapshot file — the user
	// command still runs, matching Hermes behavior.
	sourceLine := "source " + shellQuoteSnapshotPath(cfg.SnapshotPath) + " >/dev/null 2>&1 || true"
	wrapper := sourceLine + "\n" + userCommand
	return wrapper, EnvironmentSnapshotEvidence{
		Code: EvidenceSnapshotLoaded,
		Path: cfg.SnapshotPath,
	}
}

func shellQuoteSnapshotPath(path string) string {
	return "'" + strings.ReplaceAll(path, "'", "'\"'\"'") + "'"
}

package environment

import "strings"

// SubprocessHomeResolver returns the profile-local HOME that should be used
// by local shell subprocesses. It is injected from config to keep tools free of
// config package dependencies and to make the behavior directly testable.
type SubprocessHomeResolver func() (string, bool)

func EnvWithSubprocessHome(env []string, resolve SubprocessHomeResolver) []string {
	out := append([]string(nil), env...)
	if resolve == nil {
		return out
	}
	home, ok := resolve()
	home = strings.TrimSpace(home)
	if !ok || home == "" {
		return out
	}

	replaced := false
	out = out[:0]
	for _, entry := range env {
		key, _, hasValue := strings.Cut(entry, "=")
		if hasValue && key == "HOME" {
			if !replaced {
				out = append(out, "HOME="+home)
				replaced = true
			}
			continue
		}
		out = append(out, entry)
	}
	if !replaced {
		out = append(out, "HOME="+home)
	}
	return out
}

package environment

import (
	"reflect"
	"sync"
	"testing"
)

func TestEnvPassthroughRegistryRegisterCheckUnionAndClear(t *testing.T) {
	registry := NewEnvPassthroughRegistry([]string{"CONFIG_ONLY", "OPENAI_API_KEY"})

	blocked := registry.Register([]string{
		" TENOR_API_KEY ",
		"NOTION_TOKEN",
		"OPENAI_API_KEY",
		"ANTHROPIC_TOKEN",
		"",
	})
	wantBlocked := []string{"OPENAI_API_KEY", "ANTHROPIC_TOKEN"}
	if !reflect.DeepEqual(blocked, wantBlocked) {
		t.Fatalf("blocked = %#v, want %#v", blocked, wantBlocked)
	}

	for _, name := range []string{"TENOR_API_KEY", "NOTION_TOKEN", "CONFIG_ONLY"} {
		if !registry.IsAllowed(name) {
			t.Fatalf("%s should be allowed", name)
		}
	}
	for _, name := range []string{"OPENAI_API_KEY", "ANTHROPIC_TOKEN", "MISSING"} {
		if registry.IsAllowed(name) {
			t.Fatalf("%s should not be allowed", name)
		}
	}

	gotAll := registry.All()
	wantAll := []string{"CONFIG_ONLY", "NOTION_TOKEN", "TENOR_API_KEY"}
	if !reflect.DeepEqual(gotAll, wantAll) {
		t.Fatalf("All = %#v, want %#v", gotAll, wantAll)
	}

	registry.ClearRegistered()
	if registry.IsAllowed("TENOR_API_KEY") || registry.IsAllowed("NOTION_TOKEN") {
		t.Fatalf("registered vars should be cleared, all=%#v", registry.All())
	}
	if !registry.IsAllowed("CONFIG_ONLY") {
		t.Fatalf("config allowlist should remain after ClearRegistered")
	}
}

func TestEnvPassthroughDefaultRegistryIsSessionScoped(t *testing.T) {
	first := NewEnvPassthroughRegistry(nil)
	second := NewEnvPassthroughRegistry(nil)

	first.Register([]string{"TENOR_API_KEY"})
	if !first.IsAllowed("TENOR_API_KEY") {
		t.Fatal("first registry should allow registered var")
	}
	if second.IsAllowed("TENOR_API_KEY") {
		t.Fatal("second registry should not see first registry registrations")
	}
}

func TestEnvPassthroughRegistryRejectsMalformedNames(t *testing.T) {
	registry := NewEnvPassthroughRegistry([]string{"CONFIG_ONLY=value", " CONFIG_OK ", "BAD NAME", "1BAD"})

	blocked := registry.Register([]string{"TENOR_API_KEY=secret", "VALID_NAME", "BAD\nNAME", "HAS-DASH"})
	if len(blocked) != 0 {
		t.Fatalf("malformed names should be ignored, not reported as provider credential blocks: %#v", blocked)
	}

	for _, name := range []string{"CONFIG_ONLY=value", "TENOR_API_KEY=secret", "BAD NAME", "BAD\nNAME", "1BAD", "HAS-DASH"} {
		if registry.IsAllowed(name) {
			t.Fatalf("malformed candidate %q should not be allowed", name)
		}
	}
	gotAll := registry.All()
	wantAll := []string{"CONFIG_OK", "VALID_NAME"}
	if !reflect.DeepEqual(gotAll, wantAll) {
		t.Fatalf("All = %#v, want %#v", gotAll, wantAll)
	}
}

func TestEnvPassthroughRegistryBlocksProviderCredentialsCaseInsensitively(t *testing.T) {
	registry := NewEnvPassthroughRegistry([]string{" openai_api_key ", "SAFE_KEY"})

	blocked := registry.Register([]string{"anthropic_token", "TENOR_API_KEY"})
	wantBlocked := []string{"anthropic_token"}
	if !reflect.DeepEqual(blocked, wantBlocked) {
		t.Fatalf("blocked = %#v, want %#v", blocked, wantBlocked)
	}

	for _, name := range []string{"openai_api_key", "OPENAI_API_KEY", "anthropic_token", "ANTHROPIC_TOKEN"} {
		if registry.IsAllowed(name) {
			t.Fatalf("provider credential %q should not be allowed", name)
		}
	}
	gotAll := registry.All()
	wantAll := []string{"SAFE_KEY", "TENOR_API_KEY"}
	if !reflect.DeepEqual(gotAll, wantAll) {
		t.Fatalf("All = %#v, want %#v", gotAll, wantAll)
	}
}

func TestEnvPassthroughRegistryBlocksAWSCredentialTriplet(t *testing.T) {
	registry := NewEnvPassthroughRegistry([]string{
		"AWS_ACCESS_KEY_ID",
		"AWS_SECRET_ACCESS_KEY",
		"AWS_SESSION_TOKEN",
		"SAFE_KEY",
	})

	blocked := registry.Register([]string{
		"AWS_ACCESS_KEY_ID",
		"AWS_SECRET_ACCESS_KEY",
		"AWS_SESSION_TOKEN",
		"TENOR_API_KEY",
	})
	wantBlocked := []string{"AWS_ACCESS_KEY_ID", "AWS_SECRET_ACCESS_KEY", "AWS_SESSION_TOKEN"}
	if !reflect.DeepEqual(blocked, wantBlocked) {
		t.Fatalf("blocked = %#v, want %#v", blocked, wantBlocked)
	}

	for _, name := range wantBlocked {
		if registry.IsAllowed(name) {
			t.Fatalf("AWS provider credential %q should not be allowed", name)
		}
	}
	gotAll := registry.All()
	wantAll := []string{"SAFE_KEY", "TENOR_API_KEY"}
	if !reflect.DeepEqual(gotAll, wantAll) {
		t.Fatalf("All = %#v, want %#v", gotAll, wantAll)
	}
}

func TestEnvPassthroughRegistrySnapshotsProviderCredentialBlocklist(t *testing.T) {
	registry := NewEnvPassthroughRegistry(nil)

	ProviderCredentialEnvBlocklist["TEST_ONLY_PROVIDER_SECRET"] = struct{}{}
	defer delete(ProviderCredentialEnvBlocklist, "TEST_ONLY_PROVIDER_SECRET")

	if blocked := registry.Register([]string{"TEST_ONLY_PROVIDER_SECRET"}); len(blocked) != 0 {
		t.Fatalf("existing registry should not inherit later global blocklist mutations: %#v", blocked)
	}
	if !registry.IsAllowed("TEST_ONLY_PROVIDER_SECRET") {
		t.Fatal("existing registry should keep the construction-time blocklist snapshot")
	}

	fresh := NewEnvPassthroughRegistry(nil)
	if blocked := fresh.Register([]string{"TEST_ONLY_PROVIDER_SECRET"}); !reflect.DeepEqual(blocked, []string{"TEST_ONLY_PROVIDER_SECRET"}) {
		t.Fatalf("fresh registry should see current blocklist, blocked = %#v", blocked)
	}
}

func TestEnvPassthroughRegistryCanonicalizesCustomBlocklistEntries(t *testing.T) {
	ProviderCredentialEnvBlocklist[" custom_provider_token "] = struct{}{}
	defer delete(ProviderCredentialEnvBlocklist, " custom_provider_token ")

	registry := NewEnvPassthroughRegistry([]string{"CUSTOM_PROVIDER_TOKEN"})
	if registry.IsAllowed("CUSTOM_PROVIDER_TOKEN") {
		t.Fatal("configured allowlist should not bypass custom provider credentials with noncanonical blocklist spelling")
	}

	blocked := registry.Register([]string{"custom_provider_token"})
	wantBlocked := []string{"custom_provider_token"}
	if !reflect.DeepEqual(blocked, wantBlocked) {
		t.Fatalf("blocked = %#v, want %#v", blocked, wantBlocked)
	}
}

func TestEnvPassthroughRegistryConcurrentSessionAccess(t *testing.T) {
	registry := NewEnvPassthroughRegistry([]string{"CONFIG_ONLY"})

	var wg sync.WaitGroup
	for i := 0; i < 16; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 200; j++ {
				registry.Register([]string{"TENOR_API_KEY", "OPENAI_API_KEY"})
				_ = registry.IsAllowed("TENOR_API_KEY")
				_ = registry.All()
			}
		}()
	}
	wg.Wait()

	if !registry.IsAllowed("CONFIG_ONLY") {
		t.Fatal("configured allowlist should remain visible after concurrent access")
	}
	if registry.IsAllowed("OPENAI_API_KEY") {
		t.Fatal("provider credentials should remain blocked after concurrent access")
	}
}

package environment

import (
	"strings"
	"testing"
)

// TestEnvironmentSnapshotSource_RedirectsStdoutAndStderr proves the generated
// shell wrapper redirects both stdout and stderr away from the snapshot
// `source` line so macOS bash declare -x output does not leak environment
// variables into terminal tool responses (Hermes 2e6699b3 fix).
func TestEnvironmentSnapshotSource_RedirectsStdoutAndStderr(t *testing.T) {
	cfg := EnvironmentSnapshotConfig{
		Mode:         SnapshotEnabled,
		SnapshotPath: "/tmp/hermes_snapshot.sh",
	}
	userCommand := "echo hello && ls -la"

	wrapper, evidence := BuildShellWrapper(cfg, userCommand)

	if evidence.Code != "snapshot_loaded" {
		t.Fatalf("evidence.Code = %q, want snapshot_loaded", evidence.Code)
	}
	if evidence.Path != "/tmp/hermes_snapshot.sh" {
		t.Fatalf("evidence.Path = %q, want /tmp/hermes_snapshot.sh", evidence.Path)
	}

	// Locate the source line within the wrapper.
	var sourceLine string
	for _, line := range strings.Split(wrapper, "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "source ") || strings.HasPrefix(trimmed, ". ") {
			sourceLine = trimmed
			break
		}
	}
	if sourceLine == "" {
		t.Fatalf("no source line in wrapper:\n%s", wrapper)
	}

	// Source line must reference the snapshot path.
	if !strings.Contains(sourceLine, "/tmp/hermes_snapshot.sh") {
		t.Fatalf("source line missing snapshot path: %q", sourceLine)
	}

	// Source line must redirect BOTH stdout and stderr away.
	hasBothStream := strings.Contains(sourceLine, ">/dev/null 2>&1") ||
		strings.Contains(sourceLine, "&>/dev/null") ||
		strings.Contains(sourceLine, "> /dev/null 2>&1")
	if !hasBothStream {
		t.Fatalf("source line does not redirect both stdout and stderr: %q", sourceLine)
	}

	// User command must NOT have its own redirect bolted on.
	if !strings.Contains(wrapper, userCommand) {
		t.Fatalf("user command missing from wrapper:\n%s", wrapper)
	}
}

// TestEnvironmentSnapshotSource_QuotesSnapshotPath proves the snapshot path is
// shell-quoted before the source line is assembled, so spaces and apostrophes in
// profile/cache directories do not split the command or inject shell syntax.
func TestEnvironmentSnapshotSource_QuotesSnapshotPath(t *testing.T) {
	cfg := EnvironmentSnapshotConfig{
		Mode:         SnapshotEnabled,
		SnapshotPath: "/tmp/gormes snapshot/it's-live.sh",
	}

	wrapper, evidence := BuildShellWrapper(cfg, "echo still-runs")
	if evidence.Code != EvidenceSnapshotLoaded {
		t.Fatalf("evidence.Code = %q, want %q", evidence.Code, EvidenceSnapshotLoaded)
	}

	lines := strings.Split(wrapper, "\n")
	if len(lines) != 2 {
		t.Fatalf("wrapper lines = %#v, want source line plus user command", lines)
	}
	wantSourceLine := "source '/tmp/gormes snapshot/it'\"'\"'s-live.sh' >/dev/null 2>&1 || true"
	if lines[0] != wantSourceLine {
		t.Fatalf("source line = %q, want %q", lines[0], wantSourceLine)
	}
	if lines[1] != "echo still-runs" {
		t.Fatalf("user command line = %q", lines[1])
	}
}

// TestEnvironmentSnapshotSource_NoSnapshotSkipsSource proves no `source`
// command is emitted when snapshot mode is disabled or path is missing; the
// user command runs untouched.
func TestEnvironmentSnapshotSource_NoSnapshotSkipsSource(t *testing.T) {
	cases := []struct {
		name     string
		cfg      EnvironmentSnapshotConfig
		wantCode string
	}{
		{
			name:     "disabled mode",
			cfg:      EnvironmentSnapshotConfig{Mode: SnapshotDisabled, SnapshotPath: "/tmp/snapshot.sh"},
			wantCode: "snapshot_disabled",
		},
		{
			name:     "enabled but empty path",
			cfg:      EnvironmentSnapshotConfig{Mode: SnapshotEnabled, SnapshotPath: ""},
			wantCode: "snapshot_path_missing",
		},
	}
	userCommand := "echo hello"

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			wrapper, evidence := BuildShellWrapper(tc.cfg, userCommand)

			if evidence.Code != tc.wantCode {
				t.Fatalf("evidence.Code = %q, want %q", evidence.Code, tc.wantCode)
			}
			if strings.Contains(wrapper, "source ") {
				t.Fatalf("wrapper unexpectedly contains source command:\n%s", wrapper)
			}
			if strings.Contains(wrapper, "/dev/null") {
				t.Fatalf("wrapper unexpectedly contains /dev/null redirect:\n%s", wrapper)
			}
			if wrapper != userCommand {
				t.Fatalf("wrapper = %q, want unmodified user command %q", wrapper, userCommand)
			}
		})
	}
}

// TestEnvironmentSnapshotSource_DoesNotRedactUserCommandOutput proves only
// the snapshot-load line is suppressed; the actual user command's stdout and
// stderr remain visible (no /dev/null redirects bolted onto the user
// command).
func TestEnvironmentSnapshotSource_DoesNotRedactUserCommandOutput(t *testing.T) {
	cfg := EnvironmentSnapshotConfig{
		Mode:         SnapshotEnabled,
		SnapshotPath: "/tmp/snap.sh",
	}
	userCommand := "echo visible-stdout && echo visible-stderr 1>&2"

	wrapper, _ := BuildShellWrapper(cfg, userCommand)

	// Split into lines and find the user-command segment.
	lines := strings.Split(wrapper, "\n")
	var userLineIdx int = -1
	for i, line := range lines {
		if strings.Contains(line, "visible-stdout") {
			userLineIdx = i
			break
		}
	}
	if userLineIdx < 0 {
		t.Fatalf("user command not found in wrapper:\n%s", wrapper)
	}

	userLine := lines[userLineIdx]
	if strings.Contains(userLine, ">/dev/null") || strings.Contains(userLine, "&>/dev/null") {
		t.Fatalf("user command line wraps stdout/stderr in /dev/null: %q", userLine)
	}

	// User command must appear verbatim somewhere in the wrapper, not
	// rewritten to swallow output.
	if !strings.Contains(wrapper, userCommand) {
		t.Fatalf("user command not present verbatim in wrapper:\n%s", wrapper)
	}

	// Confirm there is exactly one /dev/null occurrence (the source line).
	devNullCount := strings.Count(wrapper, "/dev/null")
	if devNullCount != 1 {
		t.Fatalf("expected exactly 1 /dev/null redirect (snapshot load only), got %d in:\n%s", devNullCount, wrapper)
	}
}

// TestEnvironmentSnapshotSource_HermeticNoShellInvocation is an invariant
// guard: the builder is a pure string transformation. It must not require a
// real shell, bash, or developer environment to run.
func TestEnvironmentSnapshotSource_HermeticNoShellInvocation(t *testing.T) {
	// If BuildShellWrapper ever shells out, this test will hang or fail in
	// hermetic CI. Calling it with both modes proves it returns purely from
	// in-process string construction.
	cfgs := []EnvironmentSnapshotConfig{
		{Mode: SnapshotDisabled},
		{Mode: SnapshotEnabled, SnapshotPath: "/tmp/x.sh"},
		{Mode: SnapshotEnabled, SnapshotPath: ""},
	}
	for _, cfg := range cfgs {
		wrapper, evidence := BuildShellWrapper(cfg, "true")
		if wrapper == "" {
			t.Fatalf("empty wrapper for cfg %+v", cfg)
		}
		if evidence.Code == "" {
			t.Fatalf("empty evidence code for cfg %+v", cfg)
		}
	}
}

