package snapshot

import "strings"

// Mode controls whether the terminal-environment shell wrapper sources a
// persisted bash environment snapshot before running a user command.
type Mode int

const (
	// Disabled returns the user command verbatim. No snapshot loading is emitted.
	Disabled Mode = iota
	// Enabled prefixes the user command with a silenced `source <path>` line.
	Enabled
)

// Evidence codes for Evidence.Code.
const (
	EvidenceLoaded      = "snapshot_loaded"
	EvidenceDisabled    = "snapshot_disabled"
	EvidencePathMissing = "snapshot_path_missing"
)

// Config configures BuildShellWrapper.
type Config struct {
	// Mode selects whether to emit the snapshot-source prefix.
	Mode Mode
	// SnapshotPath is the absolute path to the persisted bash environment dump.
	SnapshotPath string
}

// Evidence is telemetry about wrapper construction.
type Evidence struct {
	// Code is one of EvidenceLoaded, EvidenceDisabled, or EvidencePathMissing.
	Code string
	// Path echoes the requested snapshot path so callers can record it.
	Path string
}

// BuildShellWrapper returns a shell-script string that, when enabled, loads a
// persisted environment snapshot with stdout AND stderr redirected to
// /dev/null before running the user command verbatim.
func BuildShellWrapper(cfg Config, userCommand string) (string, Evidence) {
	if cfg.Mode != Enabled {
		return userCommand, Evidence{
			Code: EvidenceDisabled,
			Path: cfg.SnapshotPath,
		}
	}
	if cfg.SnapshotPath == "" {
		return userCommand, Evidence{
			Code: EvidencePathMissing,
			Path: "",
		}
	}

	// Source the snapshot with both stdout and stderr redirected, then run the
	// user command verbatim on the next line. `|| true` keeps the wrapper
	// resilient to a missing/corrupt snapshot file.
	sourceLine := "source " + shellQuoteSnapshotPath(cfg.SnapshotPath) + " >/dev/null 2>&1 || true"
	wrapper := sourceLine + "\n" + userCommand
	return wrapper, Evidence{
		Code: EvidenceLoaded,
		Path: cfg.SnapshotPath,
	}
}

func shellQuoteSnapshotPath(path string) string {
	return "'" + strings.ReplaceAll(path, "'", "'\"'\"'") + "'"
}

package subprocess

import "strings"

// HomeResolver returns the profile-local HOME that should be used by local
// shell subprocesses.
type HomeResolver func() (string, bool)

// EnvWithHome overlays the resolved profile-local HOME onto env, preserving the
// input when the resolver is absent or empty.
func EnvWithHome(env []string, resolve HomeResolver) []string {
	out := append([]string(nil), env...)
	if resolve == nil {
		return out
	}
	home, ok := resolve()
	home = strings.TrimSpace(home)
	if !ok || home == "" {
		return out
	}

	replaced := false
	out = out[:0]
	for _, entry := range env {
		key, _, hasValue := strings.Cut(entry, "=")
		if hasValue && key == "HOME" {
			if !replaced {
				out = append(out, "HOME="+home)
				replaced = true
			}
			continue
		}
		out = append(out, entry)
	}
	if !replaced {
		out = append(out, "HOME="+home)
	}
	return out
}

package passthrough

import (
	"sort"
	"strings"
	"sync"
)

// defaultProviderCredentialEnvBlocklistNames names Hermes/Gormes-managed
// provider credentials that skills must not be allowed to smuggle into
// sandboxed child processes. Keep provider credential families complete; for
// example, AWS credentials are an access-key/secret/session-token triplet.
var defaultProviderCredentialEnvBlocklistNames = []string{
	"ANTHROPIC_API_KEY",
	"ANTHROPIC_AUTH_TOKEN",
	"ANTHROPIC_TOKEN",
	"AWS_ACCESS_KEY_ID",
	"AWS_SECRET_ACCESS_KEY",
	"AWS_SESSION_TOKEN",
	"AZURE_OPENAI_API_KEY",
	"COHERE_API_KEY",
	"GEMINI_API_KEY",
	"GOOGLE_API_KEY",
	"GROQ_API_KEY",
	"MISTRAL_API_KEY",
	"NOUS_API_KEY",
	"OPENAI_API_KEY",
	"OPENROUTER_API_KEY",
	"XAI_API_KEY",
}

// ProviderCredentialEnvBlocklist is the mutable provider credential blocklist
// used when new session registries are constructed. Existing registries keep a
// construction-time snapshot so later mutations cannot cross session bounds.
var ProviderCredentialEnvBlocklist = envNameSetFromList(defaultProviderCredentialEnvBlocklistNames)

// Registry is a session-scoped allowlist for environment variables that may
// pass through to sandboxed tools.
type Registry struct {
	mu         sync.RWMutex
	registered map[string]struct{}
	configured map[string]struct{}
	blocklist  map[string]struct{}
}

// NewRegistry creates a registry with config-sourced allowlist entries.
func NewRegistry(configured []string) *Registry {
	return NewRegistryWithBlocklist(configured, ProviderCredentialEnvBlocklist)
}

// NewRegistryWithBlocklist creates a registry from an explicit provider
// credential blocklist snapshot source. It exists so compatibility facades can
// preserve their exported mutable blocklist variable.
func NewRegistryWithBlocklist(configured []string, blocklist map[string]struct{}) *Registry {
	r := &Registry{
		registered: map[string]struct{}{},
		configured: map[string]struct{}{},
		blocklist:  cloneEnvNameSet(blocklist),
	}
	for _, raw := range configured {
		candidate := classifyCandidate(raw, r.blocklist)
		if !candidate.Valid || candidate.ProviderCredential {
			continue
		}
		r.configured[candidate.Name] = struct{}{}
	}
	return r
}

// Register adds skill-declared environment variables to the session allowlist
// and returns the sanitized names that were rejected as provider credentials.
func (r *Registry) Register(names []string) []string {
	if r == nil {
		return nil
	}
	r.mu.Lock()
	defer r.mu.Unlock()

	blocked := make([]string, 0)
	for _, raw := range names {
		candidate := classifyCandidate(raw, r.blocklist)
		if !candidate.Valid {
			continue
		}
		if candidate.ProviderCredential {
			blocked = append(blocked, candidate.Name)
			continue
		}
		r.registered[candidate.Name] = struct{}{}
	}
	return blocked
}

// IsAllowed reports whether name was registered for this session or listed in
// the config allowlist.
func (r *Registry) IsAllowed(name string) bool {
	if r == nil {
		return false
	}
	r.mu.RLock()
	defer r.mu.RUnlock()

	candidate := classifyCandidate(name, r.blocklist)
	if !candidate.Valid || candidate.ProviderCredential {
		return false
	}
	if _, ok := r.registered[candidate.Name]; ok {
		return true
	}
	_, ok := r.configured[candidate.Name]
	return ok
}

// All returns the sorted union of session-registered and configured allowlist
// names. Sorting keeps tool/runtime evidence deterministic.
func (r *Registry) All() []string {
	if r == nil {
		return nil
	}
	r.mu.RLock()
	defer r.mu.RUnlock()

	return sortedEnvNameUnion(r.registered, r.configured)
}

// ClearRegistered resets only the skill/session-scoped allowlist. Configured
// allowlist entries remain.
func (r *Registry) ClearRegistered() {
	if r == nil {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()

	clear(r.registered)
}

type candidate struct {
	Name               string
	Valid              bool
	ProviderCredential bool
}

func classifyCandidate(raw string, blocklist map[string]struct{}) candidate {
	name := normalizeName(raw)
	if !isValidName(name) {
		return candidate{}
	}
	return candidate{
		Name:               name,
		Valid:              true,
		ProviderCredential: isProviderCredentialName(name, blocklist),
	}
}

func normalizeName(name string) string {
	return strings.TrimSpace(name)
}

func isValidName(name string) bool {
	if name == "" {
		return false
	}
	for i := 0; i < len(name); i++ {
		b := name[i]
		if i == 0 {
			if !isNameStart(b) {
				return false
			}
			continue
		}
		if !isNamePart(b) {
			return false
		}
	}
	return true
}

func isNameStart(b byte) bool {
	return b == '_' || ('A' <= b && b <= 'Z') || ('a' <= b && b <= 'z')
}

func isNamePart(b byte) bool {
	return isNameStart(b) || ('0' <= b && b <= '9')
}

func isProviderCredentialName(name string, blocklist map[string]struct{}) bool {
	if blocklist == nil {
		return false
	}
	_, ok := blocklist[canonicalProviderCredentialName(name)]
	return ok
}

func cloneEnvNameSet(in map[string]struct{}) map[string]struct{} {
	out := make(map[string]struct{}, len(in))
	for name := range in {
		canonical := canonicalProviderCredentialName(name)
		if canonical == "" {
			continue
		}
		out[canonical] = struct{}{}
	}
	return out
}

func envNameSetFromList(names []string) map[string]struct{} {
	out := make(map[string]struct{}, len(names))
	for _, name := range names {
		canonical := canonicalProviderCredentialName(name)
		if canonical == "" {
			continue
		}
		out[canonical] = struct{}{}
	}
	return out
}

func sortedEnvNameUnion(sets ...map[string]struct{}) []string {
	size := 0
	for _, set := range sets {
		size += len(set)
	}
	union := make(map[string]struct{}, size)
	for _, set := range sets {
		for name := range set {
			union[name] = struct{}{}
		}
	}
	out := make([]string, 0, len(union))
	for name := range union {
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

func canonicalProviderCredentialName(name string) string {
	return strings.ToUpper(strings.TrimSpace(name))
}

package environment

import "github.com/TrebuchetDynamics/gormes-agent/internal/tools/environment/snapshot"

// SnapshotMode controls whether the terminal-environment shell wrapper
// sources a persisted bash environment snapshot before running a user command.
type SnapshotMode = snapshot.Mode

const (
	// SnapshotDisabled returns the user command verbatim. No snapshot loading is emitted.
	SnapshotDisabled SnapshotMode = snapshot.Disabled
	// SnapshotEnabled prefixes the user command with a silenced source line.
	SnapshotEnabled SnapshotMode = snapshot.Enabled
)

// Evidence codes for EnvironmentSnapshotEvidence.Code.
const (
	EvidenceSnapshotLoaded      = snapshot.EvidenceLoaded
	EvidenceSnapshotDisabled    = snapshot.EvidenceDisabled
	EvidenceSnapshotPathMissing = snapshot.EvidencePathMissing
)

// EnvironmentSnapshotConfig configures BuildShellWrapper.
type EnvironmentSnapshotConfig = snapshot.Config

// EnvironmentSnapshotEvidence is telemetry about wrapper construction.
type EnvironmentSnapshotEvidence = snapshot.Evidence

// BuildShellWrapper returns a shell-script string that, when enabled, loads a
// persisted environment snapshot with stdout AND stderr redirected to
// /dev/null before running the user command verbatim.
func BuildShellWrapper(cfg EnvironmentSnapshotConfig, userCommand string) (string, EnvironmentSnapshotEvidence) {
	return snapshot.BuildShellWrapper(cfg, userCommand)
}

package environment

import "github.com/TrebuchetDynamics/gormes-agent/internal/tools/environment/subprocess"

// SubprocessHomeResolver returns the profile-local HOME that should be used by
// local shell subprocesses. It is injected from config to keep tools free of
// config package dependencies and to make the behavior directly testable.
type SubprocessHomeResolver = subprocess.HomeResolver

// EnvWithSubprocessHome overlays the resolved profile-local HOME onto env.
func EnvWithSubprocessHome(env []string, resolve SubprocessHomeResolver) []string {
	return subprocess.EnvWithHome(env, resolve)
}

package environment

import "github.com/TrebuchetDynamics/gormes-agent/internal/tools/environment/passthrough"

// ProviderCredentialEnvBlocklist is the mutable provider credential blocklist
// used when new session registries are constructed. Existing registries keep a
// construction-time snapshot so later mutations cannot cross session bounds.
var ProviderCredentialEnvBlocklist = passthrough.ProviderCredentialEnvBlocklist

// EnvPassthroughRegistry is a session-scoped allowlist for environment
// variables that may pass through to sandboxed tools. It mirrors Hermes'
// ContextVar-backed registry with an explicit Go object so callers can keep
// separate sessions isolated and tests can prove no cross-session bleed.
type EnvPassthroughRegistry = passthrough.Registry

// NewEnvPassthroughRegistry creates a registry with config-sourced allowlist
// entries. Provider credentials in the configured list are ignored, matching
// Hermes' safety rule that operator config also cannot override sandbox
// credential scrubbing.
func NewEnvPassthroughRegistry(configured []string) *EnvPassthroughRegistry {
	return passthrough.NewRegistryWithBlocklist(configured, ProviderCredentialEnvBlocklist)
}

package snapshot

import (
	"strings"
	"testing"
)

func TestBuildShellWrapperLoadsSnapshotAndPreservesCommandOutput(t *testing.T) {
	wrapper, evidence := BuildShellWrapper(Config{Mode: Enabled, SnapshotPath: "/tmp/gormes snapshot/it's-live.sh"}, "echo visible")

	if evidence.Code != EvidenceLoaded {
		t.Fatalf("evidence.Code = %q, want %q", evidence.Code, EvidenceLoaded)
	}
	lines := strings.Split(wrapper, "\n")
	if len(lines) != 2 {
		t.Fatalf("wrapper lines = %#v, want source line plus command", lines)
	}
	wantSource := "source '/tmp/gormes snapshot/it'\"'\"'s-live.sh' >/dev/null 2>&1 || true"
	if lines[0] != wantSource {
		t.Fatalf("source line = %q, want %q", lines[0], wantSource)
	}
	if lines[1] != "echo visible" {
		t.Fatalf("command line = %q, want command verbatim", lines[1])
	}
}

func TestBuildShellWrapperSkipsMissingSnapshot(t *testing.T) {
	wrapper, evidence := BuildShellWrapper(Config{Mode: Enabled}, "echo visible")

	if wrapper != "echo visible" {
		t.Fatalf("wrapper = %q, want command verbatim", wrapper)
	}
	if evidence.Code != EvidencePathMissing {
		t.Fatalf("evidence.Code = %q, want %q", evidence.Code, EvidencePathMissing)
	}
}

package subprocess

import (
	"reflect"
	"testing"
)

func TestEnvWithHomeReplacesFirstHomeAndDropsDuplicates(t *testing.T) {
	got := EnvWithHome([]string{"PATH=/bin", "HOME=/old", "HOME=/older", "SHELL=/bin/sh"}, func() (string, bool) {
		return " /profile/home ", true
	})
	want := []string{"PATH=/bin", "HOME=/profile/home", "SHELL=/bin/sh"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("EnvWithHome = %#v, want %#v", got, want)
	}
}

func TestEnvWithHomePreservesEnvWhenResolverEmpty(t *testing.T) {
	input := []string{"PATH=/bin", "HOME=/old"}
	got := EnvWithHome(input, func() (string, bool) { return " ", true })
	if !reflect.DeepEqual(got, input) {
		t.Fatalf("EnvWithHome = %#v, want original %#v", got, input)
	}
	got[0] = "PATH=/changed"
	if input[0] != "PATH=/bin" {
		t.Fatalf("returned env should not alias input: %#v", input)
	}
}

package passthrough

import (
	"reflect"
	"testing"
)

func TestRegistryAllowsConfiguredAndRegisteredNamesButBlocksProviderCredentials(t *testing.T) {
	registry := NewRegistry([]string{"CONFIG_ONLY", "OPENAI_API_KEY"})

	blocked := registry.Register([]string{"TENOR_API_KEY", "ANTHROPIC_TOKEN"})
	if !reflect.DeepEqual(blocked, []string{"ANTHROPIC_TOKEN"}) {
		t.Fatalf("blocked = %#v, want ANTHROPIC_TOKEN", blocked)
	}
	if !registry.IsAllowed("CONFIG_ONLY") || !registry.IsAllowed("TENOR_API_KEY") {
		t.Fatalf("expected config and registered names to be allowed: %#v", registry.All())
	}
	if registry.IsAllowed("OPENAI_API_KEY") || registry.IsAllowed("ANTHROPIC_TOKEN") {
		t.Fatalf("provider credentials should be blocked")
	}
	wantAll := []string{"CONFIG_ONLY", "TENOR_API_KEY"}
	if got := registry.All(); !reflect.DeepEqual(got, wantAll) {
		t.Fatalf("All = %#v, want %#v", got, wantAll)
	}
}

func TestRegistrySnapshotsExplicitBlocklist(t *testing.T) {
	blocklist := map[string]struct{}{"INITIAL_SECRET": {}}
	registry := NewRegistryWithBlocklist(nil, blocklist)
	blocklist["LATER_SECRET"] = struct{}{}

	if blocked := registry.Register([]string{"INITIAL_SECRET", "LATER_SECRET"}); !reflect.DeepEqual(blocked, []string{"INITIAL_SECRET"}) {
		t.Fatalf("blocked = %#v, want only initial snapshot entry", blocked)
	}
	if !registry.IsAllowed("LATER_SECRET") {
		t.Fatalf("registry should not inherit blocklist mutations after construction")
	}
}

